package com.example.commerce.order.settlements;
import static com.example.commerce.order.settlements.SettlementModels.*;import java.time.*;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class SettlementService{private final SettlementRepository repository;public SettlementService(SettlementRepository repository){this.repository=repository;}public SettlementPage list(LocalDate from,LocalDate to){validate(from,to);return new SettlementPage(repository.find(from,to),from,to);}@Transactional public RebuildResult rebuild(LocalDate from,LocalDate to){validate(from,to);int days=0;for(var date=from;!date.isAfter(to);date=date.plusDays(1)){repository.rebuild(date);days++;}return new RebuildResult(from,to,days);}@Scheduled(cron="0 10 0 * * *",zone="UTC") public void nightly(){var today=LocalDate.now(ZoneOffset.UTC);rebuild(today.minusDays(2),today);}private void validate(LocalDate from,LocalDate to){if(from==null||to==null||from.isAfter(to)||from.plusDays(366).isBefore(to))throw new IllegalArgumentException("Settlement range must be 367 days or less");}}
